import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/HTML-Output-Options.md","filePath":"manual-en/HTML-Output-Options.md","lastUpdated":1785684581000}'),s={name:"manual-en/HTML-Output-Options.md"};function p(i,e,l,u,r,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h3 id="_3-6-html-output-options" tabindex="-1">3.6 HTML Output Options <a class="header-anchor" href="#_3-6-html-output-options" aria-label="Permalink to &quot;3.6 HTML Output Options&quot;">​</a></h3><p>To produce output in HTML format, specify -o file on the PSPP command line, optionally followed by any of the options shown in the table below to customize the output format.</p><p>-O format=html</p><p>Specify the output format. This is only necessary if the file name given on -o does not end in .html.</p><p>-O charts={template.png|none}</p><p>Sets the name used for chart files. See <a href="./Plain-Text-Output-Options">Plain Text Output Options</a>, for details.</p><p>-O borders=boolean</p><p>Decorate the tables with borders. If set to false, the tables produced will have no borders. The default value is true.</p><p>-O bare=boolean</p><p>The HTML output driver ordinarily outputs a complete HTML document. If set to true, the driver instead outputs only what would normally be the contents of the <code>body</code> element. The default value is false.</p><p>-O css=boolean</p><p>Use cascading style sheets. Cascading style sheets give an improved appearance and can be used to produce pages which fit a certain web site’s style. The default value is true.</p>',12)])])}const f=t(s,[["render",p]]);export{h as __pageData,f as default};
